output_text:
[
  {
    "id": "take_station_cart",
    "text": "A shopper is obliged to take the entrance cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "with_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "with_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "cart_and_free_hands_for_items",
    "text": "A shopper may pick up shelf items only while using a cart and not already carrying something by hand.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "hands_free": {
          "not": "handFull"
        },
        "proper_item_pickup_context": {
          "and": [
            "with_cart",
            "hands_free"
          ]
        }
      },
      "events": {
        "improper_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "proper_item_pickup_context"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "improper_item_pickup"
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "Before leaving the store, the shopper is obliged to park the cart in the return bay at the service-desk corner.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "with_cart": "hasCart",
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "park_cart_at_return_bay": {
          "pre": {
            "and": [
              "return_bay",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "park_cart_at_return_bay"
    }
  },
  {
    "id": "checkout_zone_cart_free",
    "text": "Carts are not allowed in the checkout and exit walking zone.",
    "abstraction": {
      "state_properties": {
        "checkout_exit_zone": {
          "or": [
            "at(7,2)",
            "at(7,3)",
            "at(7,4)",
            "at(8,2)",
            "at(8,3)",
            "at(8,4)",
            "at(8,5)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "with_cart": "hasCart",
        "cart_in_checkout_exit_zone": {
          "and": [
            "checkout_exit_zone",
            "with_cart"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_checkout_exit_zone"
    }
  },
  {
    "id": "drop_cart_only_at_allowed_spots",
    "text": "A shopper may leave a cart only in designated cart-parking places such as the return bay or the temporary pull-off near the milk shelf.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "milk_shelf_pull_off": "at(5,4)",
        "allowed_cart_drop_spot": {
          "or": [
            "return_bay",
            "milk_shelf_pull_off"
          ]
        },
        "with_cart": "hasCart"
      },
      "events": {
        "cart_left_at_undesignated_spot": {
          "pre": {
            "and": [
              "with_cart",
              "LEAVE_CART",
              {
                "not": "allowed_cart_drop_spot"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_left_at_undesignated_spot"
    }
  },
  {
    "id": "reclaim_temporary_cart_drop",
    "text": "If a cart is temporarily dropped at the milk-shelf pull-off, the shopper is obliged to reclaim that same cart before exiting.",
    "abstraction": {
      "state_properties": {
        "milk_shelf_pull_off": "at(5,4)",
        "cart_at_milk_pull_off": "cartAt(5,4)",
        "with_cart": "hasCart"
      },
      "events": {
        "temporary_cart_drop_at_milk": {
          "pre": {
            "and": [
              "milk_shelf_pull_off",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_at_milk_pull_off"
        },
        "reclaim_milk_pull_off_cart": {
          "pre": {
            "and": [
              "milk_shelf_pull_off",
              "cart_at_milk_pull_off",
              "PICKUP_CART"
            ]
          },
          "post": "with_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "temporary_cart_drop_at_milk",
      "discharge": "reclaim_milk_pull_off_cart"
    }
  },
  {
    "id": "front_lane_pull_aside_with_cart",
    "text": "After driving a cart down from a shopping aisle into the front entrance lane, the shopper is obliged to pull aside into the front-left refuge before returning the cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "lower_shopping_aisle_cell": {
          "or": [
            "at(1,4)",
            "at(3,4)"
          ]
        },
        "front_lane_cell": {
          "or": [
            "at(1,5)",
            "at(3,5)"
          ]
        },
        "front_left_refuge": "at(0,4)",
        "front_left_floor": "at(0,5)"
      },
      "events": {
        "descend_from_aisle_to_front_lane_with_cart": {
          "pre": {
            "and": [
              "with_cart",
              "lower_shopping_aisle_cell",
              "S"
            ]
          },
          "post": "front_lane_cell"
        },
        "pull_aside_to_front_left_refuge": {
          "pre": {
            "and": [
              "with_cart",
              "front_left_floor",
              "N"
            ]
          },
          "post": "front_left_refuge"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "descend_from_aisle_to_front_lane_with_cart",
      "discharge": "pull_aside_to_front_left_refuge"
    }
  },
  {
    "id": "front_left_queue_rejoin",
    "text": "When a shopper with a cart occupies the front-left entrance cell, they are obliged to move east to rejoin the entrance queue rather than staying there.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "front_left_entrance_cell": "at(0,5)",
        "front_left_with_cart": {
          "and": [
            "front_left_entrance_cell",
            "with_cart"
          ]
        },
        "entrance_queue_cell": "at(1,5)"
      },
      "events": {
        "rejoin_entrance_queue": {
          "pre": {
            "and": [
              "front_left_with_cart",
              "E"
            ]
          },
          "post": "entrance_queue_cell"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "front_left_with_cart",
      "discharge": "rejoin_entrance_queue"
    }
  }
]
